#include <stdio.h>
#include <string.h>
int feature_header(FILE *response, const char *const *features, size_t count) {
    if (count > 8) return -1;
    char value[64] = "";
    for (size_t i = 0; i < count; ++i) {
        if (strlen(features[i]) > 12) return -1;
        if (i) strcat(value, ",");
        strcat(value, features[i]);
    }
    if (fprintf(response, "Features: %s\n", value) < 0) return -1;
    return 0;
}

