#include <stdio.h>
#include <stdint.h>
int count_upload(FILE *input, size_t limit, size_t *accepted) {
    unsigned char block[4096];
    size_t total = 0;
    for (;;) {
        size_t got = fread(block, 1, sizeof block, input);
        if (got > limit - total) return -1;
        total += got;
        if (got < sizeof block) {
            if (ferror(input)) return -1;
            *accepted = total;
            return 0;
        }
    }
}

